head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


myDateOpts;
$(document).ready(function() {
    // 달력 기본세팅
    scwin.myDateOpts = {
        showOn: "both",
        buttonText: "달력",
        buttonImage: "/images/common/icn_calendar.gif",
        buttonImageOnly: true,
        changeMonth: true,
        changeYear: true,
        showButtonPanel: false,
        yearRange: '2011:+30'
    };
});




/*=============================================================================*
 * 입력값이 숫자인지를 확인한다
 * param : sVal 입력스트링
 * return : Boolean True이면 숫자값
 *============================================================================*/
/**
 * @method
 * @name isNumber
 * @description desc
 * @param {string} sVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.isNumber = function(sVal) {
    if (sVal.length < 1) {
        return false;
    }
    for (i = 0; i < sVal.length; i++) {
        iBit = parseInt(sVal.substring(i, i + 1)); //문자(Char)를 숫자로 변경
        if (('0' < iBit) || ('9' > iBit)) {
            //alert(i+':'+iBit+':'+'Mun');

        } else {
            return false;
        }
    }
    return true;
};

/*=============================================================================*
 * 입력값이 숫자인지를 확인하고 포멧을 만들어준다
 * param : sdateVal 입력스트링
 * return : Boolean True이면 숫자값
 *============================================================================*/
/**
 * @method
 * @name chkDate
 * @description desc
 * @param {string} sdateVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.chkDate = function(sdateVal) {
    var dateVal = eval(sdateVal).getValue();
    if (dateVal.length < 1) {
        return;
    }
    var dateVal2 = scwin.rtnNumber(dateVal);
    window.status = dateVal2.length;
    if (dateVal2.length < 1) {
        eval(sdateVal).setValue("");
    } else if (dateVal2.length >= 1 && dateVal2.length < 8) {
        eval(sdateVal).setValue(dateVal2);
    } else if (dateVal2.length == 8) {
        eval(sdateVal).setValue(dateVal2.substring(0, 4) + "-" + dateVal2.substring(4, 6) + "-" + dateVal2.substring(6, 8));
    } else if (dateVal2.length > 8) {
        eval(sdateVal).setValue(dateVal2.substring(0, 4) + "-" + dateVal2.substring(4, 6) + "-" + dateVal2.substring(6, 8));
    }
};


/*
	내    용 : 일자값 체크 (8문자 수치여부, 년월일값의 범위, 윤년)
	파라미터 : pDate - 체크할 날짜
	Return값 : TRUE or FALSE
*/
/**
 * @method
 * @name fCheckDate
 * @description desc
 * @param {string} pDate2 desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fCheckDate = function(pDate2) {
    // 일자값 저장 배열
    var vDateArray = new Array(3);
    // 값이 없으면 false 리턴
    if (pDate2 == "") {
        return false;
    }
    var pDate = scwin.rtnNumber(pDate2);
    // 값이 없으면 false 리턴
    if (pDate == "") {
        return false;
    }
    // 길이가 8 이 아니면 false 리턴
    if (pDate.length != 8) {
        return false;
    }

    // 길이대로(년:4, 월:2, 일:2) 잘라서 배열에 저장
    vDateArray[0] = pDate.substring(0, 4);
    vDateArray[1] = pDate.substring(4, 6);
    vDateArray[2] = pDate.substring(6, 8);


    // 년도값이 0 부터 9999 사이의 수치가 아니면 false 리턴
    if (eval(vDateArray[0]) < 0 || eval(vDateArray[0]) > 9999) {
        return false;
    }

    // 월값이 1 부터 12 사이의 수치가 아니면 false 리턴
    if (eval(vDateArray[1]) < 1 || eval(vDateArray[1]) > 12) {
        return false;
    }

    // 일값이 1 부터 31 사이의 수치가 아니면 false 리턴
    if (eval(vDateArray[2]) < 1 || eval(vDateArray[2]) > 31) {
        return false;
    }

    // 월값이 길이가 1 이면 앞에 "0" 을 붙인다
    if (vDateArray[1].length == 1) vDateArray[1] = "0" + vDateArray[1];

    // 일값이 길이가 1 이면 앞에 "0" 을 붙인다
    if (vDateArray[2].length == 1) vDateArray[2] = "0" + vDateArray[1];

    // 30 일까지 있는 달의 일 체크
    if ((eval(vDateArray[1]) == 4 || eval(vDateArray[1]) == 6 || eval(vDateArray[1]) == 9 || eval(vDateArray[1]) == 11) && eval(vDateArray[2]) == 31) {
        return false;
    }

    // 윤년일 경우
    if (((eval(vDateArray[0]) % 4 == 0 && eval(vDateArray[0]) % 100 != 0) || eval(vDateArray[0]) % 400 == 0)) {
        // 2 월의 일 체크
        if (eval(vDateArray[1]) == 2 && eval(vDateArray[2]) > 29) {
            return false;
        }
    }
    // 윤년이 아닐 경우
    else {
        // 2월의 일 체크
        if (eval(vDateArray[1]) == 2 && eval(vDateArray[2]) > 28) {
            return false;
        }
    }
    return true;
};

/*=============================================================================*
 * 날짜컬럼에 포커스들어갈경우 "-" 제거해준다
 * param : sdateVal 입력스트링
 * return : Boolean True이면 숫자값
 *============================================================================*/
/**
 * @method
 * @name cal_offMask
 * @description desc
 * @param {string} sdateVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cal_offMask = function(sdateVal) {
    var dateVal = eval(sdateVal).getValue();
    if (dateVal.length < 1) {
        return false;
    }

    //eval(sdateVal).value = "";

    //eval(sdateVal).value = dateVal.replace(/\-/g, '');

};





/*=============================================================================*
 * 입력값이 숫자인지를 확인한다
 * param : sVal 입력스트링
 * return : Boolean True이면 숫자값
 *============================================================================*/

/**
 * @method
 * @name rtnNumber
 * @description desc
 * @param {string} sVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.rtnNumber = function(sVal) {
    var rtnVal = "";
    if (sVal.length < 1) {
        return rtnVal;
    }
    for (i = 0; i < sVal.length; i++) {
        iBit = parseInt(sVal.substring(i, i + 1)); //문자(Char)를 숫자로 변경
        if (('0' <= iBit) && ('9' >= iBit)) {
            rtnVal = rtnVal + iBit;
        }
    }
    return rtnVal;
};

/*=============================================================================*
 * 입력값이 숫자인지를 확인한다. (' '까지 괜찮음)
 * param : sVal 입력스트링
 * return : Boolean True이면 숫자값
 *============================================================================*/
/**
 * @method
 * @name isNumberSpace
 * @description desc
 * @param {string} sVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.isNumberSpace = function(sVal) {
    if (sVal.length < 1) {
        return false;
    }
    for (var i = 0; i < sVal.length; i++) {
        sBitData = sVal.substring(i, i + 1); //문자열의 문자(char)를 넣는다
        if (sBitData == ' ') {

        } else {
            iBit = parseInt(sVal.substring(i, i + 1)); //문자(char)를 숫자로
            if (('0' < iBit) || ('9' > iBit) || (' ' == sBitData)) {

            } else {
                return false;
            }
        }
    }
    return true;
};

/*=============================================================================*
 * sVal 값이 숫자인지를 확인한다.('.'까지 괜찮음)
 *
 * param : sVal 입력스트링
 *
 * return : Boolean  True이면 숫자값
 *============================================================================*/
/**
 * @method
 * @name isNumberDot
 * @description desc
 * @param {string} sVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.isNumberDot = function(sVal) {
    if (sVal.length < 1) {
        return false;
    }
    var result = 0;
    var position = 0;
    var bMinus;
    //마이너스 부호의 갯수를 카운트하여 올바른지 확인
    for (position = 0; position < sVal.length; position++) {
        if (scwin.getAt(sVal, position) == '-') {
            result += 1;
        }
    }
    if (result > 1) return false;
    result = 0;
    //소수점의 갯수를 카운트하여 올바른지 확인
    for (position = 0; position < sVal.length; position++) {
        if (scwin.getAt(sVal, position) == '.') {
            result += 1;
        }
    }
    if (result > 1) return false;
    //마이너스 부호를 가지고 있는지 확인. 있다면 부호는 빼낸다.
    if (sVal.substr(0, 1) == '-') {
        bMinus = true;
        sVal = sVal.substring(1, sVal.length);
    }
    //맨앞에 소수점이 있거나 맨 뒤에 있을 경우 0 을 추가해 줌.
    if (sVal.substring(0, 1) == '.') sVal = '0' + sVal;

    else if (sVal.substring(sVal.length - 1, sVal.length) == '.') sVal = sVal + '0';

    //검사.
    for (var position = 0; position < sVal.length; position++) {
        if ((scwin.getAt(sVal, position) < '0' || scwin.getAt(sVal, position) > '9') && scwin.getAt(sVal, position) != '.') return false;
    }
    return true;
};
/**
 * @method
 * @name getAt
 * @description desc
 * @param {string} sVal desc
 * @param {string} position desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getAt = function(sVal, position) {
    return sVal.substring(position, position + 1);
};

/*=============================================================================*
 * 앞자리의 연속된 Zero 값을 자른다.
 * param : sVal 입력스트링
 * return : String  Zero값을 자른 값
 *============================================================================*/
/**
 * @method
 * @name trimZero
 * @description desc
 * @param {string} sVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.trimZero = function(sVal) {
    var i;
    i = 0;
    while (sVal.substring(i, i + 1) == '0') {
        i++;
    }
    return sVal.substring(i);
};

/*=============================================================================*
 * 입력값의 앞에 정해진 자리수만큼 0을 채운다.
 * param : sVal 입력스트링, iSize
 * return : String
 *============================================================================*/
/**
 * @method
 * @name fillZero
 * @description desc
 * @param {string} sVal desc
 * @param {string} iSize desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fillZero = function(sVal, iSize) {
    while (sVal.length < iSize) {
        sVal = "0" + sVal;
    }
    return sVal;
};

/*=============================================================================*
 * 길이가1인 경우 앞에 "0"을 붙인다.
 *
 * param : sVal 입력스트링
 *
 * return : String  "0"값을 포함하는 값
 *============================================================================*/
/**
 * @method
 * @name addZero
 * @description desc
 * @param {string} sVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.addZero = function(sVal) {
    var iLen = sVal.length; //인수값의 길이를 구한다.
    if (iLen == 1) {
        sVal = "0" + sVal;
    } else if (iLen == 0) {
        return;
    }
    return sVal;
};

/*=============================================================================*
 * 날짜 여부를 확인한다.(월일 or 년월 or 년월일)
 *
 * param : sYmd 입력스트링(MMDD or YYYYMM or YYYYMMDD)
 *
 * return : Boolean true이면 날짜 범위임
 *
 * 수정   : 월이나 일에 00 입력시 스크립트 에러. trimZero 부분을 수정(2003/11/19)
 *============================================================================*/
/**
 * @method
 * @name isDate
 * @description desc
 * @param {string} sYmd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.isDate = function(sYmd) {
    var bResult; // 결과값을 담는 변수(Boolean)
    switch (sYmd.length) {
        case 4: //월일
            bResult = scwin.isDateMD(sYmd);
            break;
        case 6: //년월
            bResult = scwin.isDateYM(sYmd);
            break;
        case 8: //년월일
            bResult = scwin.isDateYMD(sYmd);
            break;
        default:
            bResult = false; // 날짜 값이 아님
            break;
    }
    return bResult;
};

/*=============================================================================*
 * 날짜 여부를 확인한다.(년월일)
 *
 * param : sYmd 입력스트링(YYYYMMDD)
 *
 * return : Boolean true이면 날짜 범위임
 *============================================================================*/
/**
 * @method
 * @name isDateYMD
 * @description desc
 * @param {string} val desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.isDateYMD = function(val) {
    var sYmd = val.getValue().replace(/\-/g, '');
    // 길이 확인      //@@ 12.5 순서 변경
    if (sYmd.length > 0) {
        if (sYmd.length != 8) {
            alert('일자를 모두 입력하십시오');
            return false;
        }
        // 숫자 확인
        if (!scwin.isNumber(sYmd)) {
            alert('날짜는 숫자만 입력하십시오');
            return false;
        }
        var iYear = parseInt(sYmd.substring(0, 4), 10); // 년도 입력(YYYY)
        var iMonth = parseInt(sYmd.substring(4, 6), 10); //월입력(MM)
        var iDay = parseInt(sYmd.substring(6, 8), 10); //일자입력(DD)
        if ((iMonth < 1) || (iMonth > 12)) {
            alert(iMonth + '월의 입력이 잘못 되었습니다.');
            val.setValue("");
            return false;
        }

        //각 달의 총 날수를 구한다
        var iLastDay = scwin.lastDay(sYmd.substring(0, 6)); // 해당월의 마지말날 계산
        if ((iDay < 1) || (iDay > iLastDay)) {
            alert(iMonth + '월의 일자는 1 - ' + iLastDay + '까지입니다.');
            val.setValue("");
            return false;
        }
        val.setValue(sYmd.substr(0, 4) + "-" + sYmd.substr(4, 2) + "-" + sYmd.substr(6, 2));
    }
    return true;
};

/*=============================================================================*
 * 포커스가 들어가면 데이터 클리어
 *
 * param : vla 입력스트링(Object)
 *
 * return : -를 뺀 문자열로 return
 *============================================================================*/
/**
 * @method
 * @name dataDel
 * @description desc
 * @param {string} obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.dataDel = function(obj) {
    obj.val(obj.val().replace(/\-/g, ''));
};

/*=============================================================================*
 * 날짜 여부를 확인한다.(월일)
 *
 * param : sMD 입력스트링(MMDD)
 *
 * return : Boolean true이면 날짜 범위임
 *============================================================================*/
/**
 * @method
 * @name isDateMD
 * @description desc
 * @param {string} sMD desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.isDateMD = function(sMD) {
    // 숫자 확인
    if (!scwin.isNumber(sMD)) {
        alert('숫자만 입력하십시오');
        return false;
    }
    // 길이 확인
    if (sMD.length != 4) {
        alert('일자를 모두 입력하십시오');
        return false;
    }
    var iMonth = parseInt(sMD.substring(0, 2), 10); //해당월을 숫자값으로
    var iDay = parseInt(sMD.substring(2, 4), 10); //해당일을 숫자값으로
    if ((iMonth < 1) || (iMonth > 12)) {
        alert(iMonth + '월의 입력이 잘못 되었습니다.');
        return false;
    }

    //각 달의 총 날수를 구한다
    if (iMonth < 8) {
        var iLastDay = 30 + (iMonth % 2);
    } else {
        var iLastDay = 31 - (iMonth % 2);
    }
    if (iMonth == 2) {
        iLastDay = 29;
    }
    if ((iDay < 1) || (iDay > iLastDay)) {
        alert(iMonth + '월의 일자는 1 - ' + iLastDay + '까지입니다.');
        return false;
    }
    return true;
};

/*=============================================================================*
 * 날짜 여부를 확인한다.(년월)
 *
 * param : sYM 입력스트링(YYYYMM)
 *
 * return : Boolean true이면 날짜 범위임
 *============================================================================*/
/**
 * @method
 * @name isDateYM
 * @description desc
 * @param {string} sYM desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.isDateYM = function(sYM) {
    // 숫자 확인
    if (!scwin.isNumber(sYM)) {
        alert('날짜는 숫자만 입력하십시오');
        return false;
    }
    // 길이 확인
    if (sYM.length != 6) {
        alert('일자를 모두 입력하십시오');
        return false;
    }
    var iYear = parseInt(sYM.substring(0, 4), 10); //년도값을 숫자로
    var iMonth = parseInt(sYM.substring(4, 6), 10); //월을 숫자로

    if ((iMonth < 1) || (iMonth > 12)) {
        alert(iMonth + '월의 입력이 잘못 되었습니다.');
        return false;
    }
    return true;
};


/*=============================================================================*
 * 년월을 입력받아 마지막 일를 반환한다(년월)
 *
 * param : sYM 입력스트링(YYYYMM)
 *
 * return : String 해당월의 마지막날
 *============================================================================*/
/**
 * @method
 * @name lastDay
 * @description desc
 * @param {string} sYM desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.lastDay = function(sYM) {
    if (sYM.length != 6) {
        alert("정확한 년월을 입력하십시오.");
        return;
    }
    if (!scwin.isDateYM(sYM)) {
        return;
    }
    daysArray = new makeArray(12); // 배열을 생성한다.
    for (i = 1; i < 8; i++) {
        daysArray[i] = 30 + (i % 2);
    }
    for (i = 8; i < 13; i++) {
        daysArray[i] = 31 - (i % 2);
    }
    var sYear = sYM.substring(0, 4) * 1;
    var sMonth = sYM.substring(4, 6) * 1;
    if (((sYear % 4 == 0) && (sYear % 100 != 0)) || (sYear % 400 == 0)) {
        daysArray[2] = 29;
    } else {
        daysArray[2] = 28;
    }
    return daysArray[sMonth].toString();
};

/*=============================================================================*
 * 대소문자를 포함한 영문자인지 확인한다.
 *
 * param : sVal 입력문자열
 *
 * return : Boolean true이면 알파벳
 *============================================================================*/
/**
 * @method
 * @name isAlpha
 * @description desc
 * @param {string} sVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.isAlpha = function(sVal) {
    // Alphabet 값
    var sAlphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    var iLen = sVal.length; //입력값의 길이
    for (i = 0; i < iLen; i++) {
        if (sAlphabet.indexOf(sVal.substring(i, i + 1)) < 0) {
            alert("허용된 문자가 아닙니다.\n영문으로 입력해 주세요.");
            return false;
        }
    }
    return true;
};

/*=============================================================================*
 * 영문자와 숫자 구성된 문자열인지 확인
 *
 * param : sVal 입력문자열
 *
 * return : Boolean true이면 영문자,숫자로 구성된 문자열
 *============================================================================*/
/**
 * @method
 * @name isAlphaNumeric
 * @description desc
 * @param {string} sVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.isAlphaNumeric = function(sVal) {
    var sAlphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890";
    var iLen = sVal.length;
    for (i = 0; i < iLen; i++) {
        if (sAlphabet.indexOf(sVal.substring(i, i + 1)) < 0) {
            return false;
        }
    }
    return true;
};

/*=============================================================================*
 * 문자열의 길이를 return (한글:2자)
 *
 * param : sVal 입력문자열
 *
 * return : int 입력문자열의 길이
 *============================================================================*/
/**
 * @method
 * @name strLength
 * @description desc
 * @param {string} sVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.strLength = function(sVal) {
    var sBit = ''; // 문자열의 문자(Char)
    var iLen = 0; //문자열 길이
    for (i = 0; i < sVal.length; i++) {
        sBit = sVal.charAt(i);
        if (escape(sBit).length > 4) {
            iLen = iLen + 2;
        } else {
            iLen = iLen + 1;
        }
    }
    return iLen;
};

/*=============================================================================*
