 * param : sVal 입력객체, iSize1 정수자릿수, iSize2 소수자릿수
 * return : boolean
 *============================================================================*/
/**
 * @method
 * @name isMoneyNumber5
 * @description desc
 * @param {string} sVal desc
 * @param {string} iSize1 desc
 * @param {string} iSize2 desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.isMoneyNumber5 = function(sVal, iSize1, iSize2) {
    if (scwin.isMoneyNumber(sVal)) // ,나 .가 들어가는 숫자인지 확인

    {
        var e = sVal.getValue();
        e = e.split(".");
        e[0] = scwin.numOffMask(e[0]);
        if (!e[1]) {
            e[1] = 0;
        }
        var aVal = e[0] + "." + e[1];
        if (scwin.isNumberDot(aVal)) {
            // 입력된 값이 설정된 정수자릿수 또는 소숫점 이하보다 크면 false
            if (e[0].length > iSize1 || e[1].length > iSize2) return false;

            else return true;
        } else {
            return false;
        }
    } else {
        return false;
    }
};



/*=============================================================================*
 * 소수점 숫자표현(소수점 위의 3자리마다 "," 맞춤)
 * param : val
 *
 * return : String
 *============================================================================*/
/**
 * @method
 * @name getMoneyType
 * @description desc
 * @param {string} val desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getMoneyType = function(val) {
    if (typeof val == "number") {
        val = val.toString();
    }
    var value = scwin.getOnlyNumberDot(val);
    var sResult = "";
    if (value.length == 0) {
        alert("숫자만 입력하십시오.");
        return;
    }
    if (!scwin.isMoneyNumber(value)) {
        alert("숫자만 입력하십시오.");
        return;
    }
    var nI;
    var nJ = -1;
    var subOne;
    var flag = false;
    for (nI = value.length - 1; nI >= 0; nI--) {
        subOne = value.substring(nI, nI + 1);
        sResult = subOne + sResult;
        if (subOne == '.') {
            flag = true;
        }
        if (flag == true) {
            nJ = nJ + 1;
        }
        if ((nJ % 3 == 0) && (nI != 0) && (nJ != 0)) {
            sResult = "," + sResult;
        }
    }
    return sResult;
};

/*=============================================================================*
 * 부호가 있는 소수점 숫자표현(소수점 위의 3자리마다 "," 맞춤)
 *
 * param : val
 *
 * return : String
 *============================================================================*/
/**
 * @method
 * @name getSignMoneyType
 * @description desc
 * @param {string} val desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getSignMoneyType = function(val) {
    if (typeof val == "number") {
        val = val.toString();
    }
    var s1 = val.substring(0, 1);
    var slen = val.length;
    var sign = "";
    var ret = "";
    if (val == "-Infinity") {
        return "0";
    }
    if (slen > 1) {
        if (s1 == "-") {
            sign = "-";
            ret = sign + scwin.getMoneyType(val.substring(1, slen));
        } else {
            ret = scwin.getMoneyType(val);
        }
    } else {
        ret = val;
    }
    return ret;
};

/*=============================================================================*
 * 콤마를 제거한 숫자형태 문자열로 반환(부호와 소수점도 없앰)
 *
 * param : val
 *
 * return : String
 *============================================================================*/
/**
 * @method
 * @name getOnlyNumber
 * @description desc
 * @param {string} val desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getOnlyNumber = function(val) {
    var value = "";
    var abit;
    if (typeof val != "number" && typeof val != "string") {
        return "0";
    }
    if (val.length < 1) {
        return "0";
    }
    if (val == "NaN") {
        return "0";
    }
    if (val == "-Infinity") {
        return "0";
    }
    for (i = 0; i < val.length; i++) {
        abit = parseInt(val.substring(i, i + 1));
        if (('0' < abit) || ('9' > abit)) {
            value.setValue(value + abit);
        }
    }
    return value;
};


/*=============================================================================*
 * 콤마를 제거한 숫자형태 문자열로 반환(부호, 소수점 그대로)
 *
 * param : val
 *
 * return : String
 *============================================================================*/
/**
 * @method
 * @name getOnlyNumberDot
 * @description desc
 * @param {string} val desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getOnlyNumberDot = function(val) {
    if (typeof val != "number" && typeof val != "string") {
        return "0";
    }
    if (val.length < 1) {
        return "0";
    }
    if (val == "NaN") {
        return "0";
    }
    if (val == "-Infinity") {
        return "0";
    }
    var value = "";
    var abit; // 소수부분

    var delimter = val.indexOf(".");
    var numberInteger = ""; // 정수부분

    if (delimter < 0) {
        numberInteger = val;
        abit = '';
    } else {
        numberInteger = val.substring(0, delimter);
        abit = val.substring(delimter + 1);
    }
    var number = "";
    var leng = numberInteger.length;
    for (i = 0; i < leng; i++) {
        var tmp = numberInteger.substring(i, i + 1);
        if (tmp != ",") {
            number = number + tmp;
        }
    }
    if (abit.length == 0) {
        value.setValue(number);
    } else {
        value.setValue(number + "." + abit);
    }
    return value;
};



/*=============================================================================*
 * 콤마를 제거한 부호가 있는 숫자형태 문자열로 반환
 *
 * param : val
 *
 * return : String
 *============================================================================*/
/**
 * @method
 * @name getOnlySignNumber
 * @description desc
 * @param {string} val desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getOnlySignNumber = function(val) {
    if (val == "-") return 0;
    var price = eval(scwin.getOnlyNumber(val));
    if (val.substring(0, 1) == "-") {
        price *= -1;
    }
    return price;
};

/*=============================================================================*
 * 조회조건 시작일과 종료일 입력 유효성 확인 - 컨트롤 이용
 *
 * param : fromDate, toDate
 *
 * return : boolean
 *============================================================================*/
/**
 * @method
 * @name chkPeriod_Emedit
 * @description desc
 * @param {string} fromDate desc
 * @param {string} toDate desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.chkPeriod_Emedit = function(fromDate, toDate) {
    var fromDate = fromDate.replace(/\-/g, '');
    var toDate = toDate.replace(/\-/g, '');
    if (fromDate == "") {
        return false;
    } else if (toDate == "") {
        return false;
    } else if (fromDate > toDate) {
        alert("마지막일이 시작일보다 작습니다.");
        return false;
    }
    return true;
};


/*=============================================================================*
 * 조회조건 시작일과 종료일이 지정한 년도보다 작은지 판단
 *
 * param : fromDate, toDate, yearCnt
 *
 * return : boolean
 *============================================================================*/
/**
 * @method
 * @name chkPeriod_year
 * @description desc
 * @param {string} fromDate desc
 * @param {string} toDate desc
 * @param {string} yearCnt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.chkPeriod_year = function(fromDate, toDate, yearCnt) {
    var fromDate = fromDate.replace(/\-/g, '');
    var toDate = toDate.replace(/\-/g, '');
    var from_date = new Date(fromDate.substring(0, 4), fromDate.substring(4, 6), fromDate.substring(6, 8), "00", "00"); //시작일
    var to_date = new Date(toDate.substring(0, 4), toDate.substring(4, 6), toDate.substring(6, 8), "00", "00"); //종료일
    var day = 1000 * 3600 * 24; //24시간
    var day_interval = parseInt((to_date - from_date) / day);
    if (day_interval > (365 * yearCnt) + 1) {
        alert('조회기간은 ' + yearCnt + '년 이내만 가능합니다.');
        return false;
    }
    return true;
};


/*=============================================================================*
 * 앞뒤 공백을 제거한다.
 *
 * param : sVal
 *
 * return : String
 *============================================================================*/
/**
 * @method
 * @name Trim
 * @description desc
 * @param {string} sVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Trim = function(sVal) {
    return (scwin.LTrim(scwin.RTrim(sVal)));
};

/*=============================================================================*
 * 앞 공백을 제거한다.
 *
 * param : sVal
 *
 * return : String
 *============================================================================*/
/**
 * @method
 * @name LTrim
 * @description desc
 * @param {string} sVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.LTrim = function(sVal) {
    var i;
    i = 0;
    while (sVal.substring(i, i + 1) == ' ') {
        i++;
    }
    return sVal.substring(i);
};

/*=============================================================================*
 * 뒤 공백을 제거한다.
 *
 * param : sVal
 *
 * return : String
 *============================================================================*/
/**
 * @method
 * @name RTrim
 * @description desc
 * @param {string} sVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.RTrim = function(sVal) {
    var i = sVal.length - 1;
    while (i >= 0 && sVal.substring(i, i + 1) == ' ') {
        i--;
    }
    return sVal.substring(0, i + 1);
};

//------------------------------------------------------------------------------
// DESCRIPTION  : 공백문자 제거
// 함수명       : MTrim(공백이 있는 문자열)
// Return Value : 공백이 제거된 문자열
//------------------------------------------------------------------------------
/**
 * @method
 * @name MTrim
 * @description desc
 * @param {string} sVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.MTrim = function(sVal) {
    var strOri = sVal;
    var space = " ";
    while (strOri.indexOf(space) != -1) {
        strOri = strOri.replace(space, "");
    }
    return strOri;
};

/*=============================================================================*
 * 공백만 존재하거나 아무것도 없는지 확인한다.
 *
 * param : sVal
 *
 * return : boolean (true이면 공백이나 Empty이다)
 *============================================================================*/
/**
 * @method
 * @name isEmpty
 * @description desc
 * @param {string} sVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.isEmpty = function(sVal) {
    if (scwin.MTrim(sVal) == '') {
        return true;
    }
    return false;
};

