/*=============================================================================*
 * 완료된 날짜값에 대해 "/" 추가
 * param : me(value)
 * return : String
 *============================================================================*/
/**
 * @method
 * @name calOnMask
 * @description desc
 * @param {string} me desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.calOnMask = function(me) {
    if (event.keyCode < 48 || event.keyCode > 57) {
        //숫자외금지
        event.returnValue = false;
    }
    if (me.length > 3) {
        var a1 = me.substring(0, 4) + "-";
        var a2 = me.substr(4, me.length);
        var a3 = "";
        if (me.length > 5) {
            a2 = me.substring(4, 6) + "-0";
            a3 = me.substr(6, me.length);
        }
        me = a1 + a2 + a3;
    }
    return me;
};

