/*=============================================================================*
 * 오늘 날짜 생성 ( "/" 붙여서 리턴)
 *
 * param :
 *
 * return : todate
 *============================================================================*/
/**
 * @method
 * @name todate
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.todate = function() {
    var now = new Date();
    var jyear = now.getYear();
    var month = now.getMonth() + 1;
    var jmonth = month + "";
    if (jmonth.length < 2) {
        jmonth = "0" + jmonth;
    }
    var dat = now.getDate();
    var jdate = dat + "";
    if (jdate.length < 2) {
        jdate = "0" + jdate;
    }

    //var day=Birdy.getDay()//요일
    var tdy = jyear + "/" + jmonth + "/" + jdate;
    return tdy;
};


/*--------------------------------------------------------------------------------------------
 Spec	  : 숫자입력시 3자리마다 자동으로 콤마 찍기
 Argument : string
 Return   : string
 Example  : onkeyup="comma_value(this)"
---------------------------------------------------------------------------------------------*/
/**
 * @method
 * @name comma_value
 * @description desc
 * @param {string} sval desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.comma_value = function(sval) {
    if (event.keyCode != 9) {
        var cur = sval.getValue();
        var setMinus = 0;
        if (cur.charAt(0) == "-") {
            setMinus = 1;
        }
        cur = cur.replace(/[^.0-9]/g, "");
        cur = cur.replace(/[.]+/g, ".");
        if (setMinus == 1) sval.setValue("-" + scwin.formatNumbertoString(cur));

        else sval.setValue(scwin.formatNumbertoString(cur));
    }
};


/*--------------------------------------------------------------------------------------------
 Spec	  : 숫자입력시 3자리마다 자동으로 콤마 찍기
 Argument : string
 Return   : string
 Example  : onkeyup="comma_value(str)"
---------------------------------------------------------------------------------------------*/
/**
 * @method
 * @name formatNumbertoString
 * @description desc
 * @param {string} cur desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.formatNumbertoString = function(cur) {
    leftString = cur;
    rightString = ".";
    dotIndex = 0;
    for (i = 0; i < cur.length; i++) {
        // 1) '.'이 처음에 입력 되었을때 앞에 0을 더해 "0."을 리턴
        // 2) "0."이외의 입력 일 때 "0"만 리턴
        if (cur.charAt(i) == "." || (cur.length > 1 && cur.charAt(0) == "0" && cur.charAt(1) != ".")) {
            dotIndex = i;
            if (dotIndex == 0) {
                if (cur.charAt(0) == ".") leftString = "0.";

                else leftString = "";
                return leftString;
            }
            break;
        }
    }
    if (dotIndex != 0) //dot가 있을 경우..

    {
        leftString = cur.substr(0, dotIndex);
        rightString = cur.substr(dotIndex + 1);
        rightString = rightString.replace(/\./g, "");
    } else
    //없으면..

    {
        leftString = cur;
    }
    len = leftString.length - 3;
    while (len > 0) {
        leftString = leftString.substr(0, len) + "," + leftString.substr(len);
        len -= 3;
    }
    if (rightString != ".") return (leftString + "." + rightString);

    else return leftString;
};

