/*=============================================================================*
 * 입력완료된 숫자값에 대하여 콤마를 찍어줄때 사용(소수점 이하 처리 안됨)
 * 콤마 형식을 사용할 경우에는 onkeyup이벤트로 사용하기 바라며,
 * 다음의 펑션을 호출할때는 comma_value(me) 펑션을 호출하기 바람.
 * param : value
 *============================================================================*/
/**
 * @method
 * @name numOnMask
 * @description desc
 * @param {string} me desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.numOnMask = function(me) {
    var tmpH = null;
    if (me.charAt(0) == "-") {
        //음수가 들어왔을때 '-'를 빼고적용되게..
        tmpH = me.substring(0, 1);
        me = me.substring(1, me.length);
    } //me.indexOf('-')
    if (me.length > 3) {
        var c = 0;
        var myArray = new Array();
        for (var i = me.length; i > 0; i = i - 3) {
            myArray[c++] = me.substring(i - 3, i);
        }
        myArray.reverse();
        me = myArray.join(",");
    }
    if (tmpH) {
        me = tmpH + me;
    }
    return me;
};

