scwin.numOnMask2 = function(me) {
    var tmpH;
    if (!scwin.isMoneyNumber4(me)) {
        if (me.charAt(0) == "-") {
            //음수가 들어왔을때 '-'를 빼고적용되게..
            tmpH = me.substring(0, 1);
            me = me.substring(1, me.length);
        } //me.indexOf('-')
        if (me.length > 3) {
            var c = 0;
            var myArray = new Array();
            for (var i = me.length; i > 0; i = i - 3) {
                myArray[c++] = me.substring(i - 3, i);
            }
            myArray.reverse();
            me = myArray.join(",");
        }
        if (tmpH) {
            me = tmpH + me;
        }
    } else {
        var e = me;
        e = e.split(".");
        var myStr = e[0];
        //alert(myStr);
        if (myStr.charAt(0) == "-") {
            //음수가 들어왔을때 '-'를 빼고적용되게..
            tmpH = myStr.substring(0, 1);
            myStr = myStr.substring(1, me.length);
        } //me.indexOf('-')
        if (myStr.length > 3) {
            var c = 0;
            var myArray = new Array();
            for (var i = myStr.length; i > 0; i = i - 3) {
                myArray[c++] = myStr.substring(i - 3, i);
            }
            myArray.reverse();
            myStr = myArray.join(",");
        }
        if (tmpH) {
            me = tmpH + myStr + "." + e[1];
        } else {
            me = myStr + "." + e[1];
        }
    }
    return me;
};

// 입력 완료된 숫자 값에 컴마를 적용하고 소수점 이하는 삭제한다
// return : String
/**
 * @method
 * @name numOnMask3
 * @description desc
 * @param {string} me desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.numOnMask3 = function(me) {
    //단순히 값에 컴마를 적용할때 사용
    var tmpH;
    if (scwin.isMoneyNumber3(me)) {
        // 양수&음수 체크 (true : 양수, false : 음수)
        var e = me;
        e = e.split(".");
        var myStr = e[0];
        if (myStr.length > 3) {
            var c = 0;
            var myArray = new Array();
            for (var i = myStr.length; i > 0; i = i - 3) {
                myArray[c++] = myStr.substring(i - 3, i);
            }
            myArray.reverse();
            myStr = myArray.join(",");
        }
        me = myStr;
    } else {
        // 음수 일때
        var e = me;
        e = e.split(".");
        var myStr = e[0];
        if (myStr.charAt(0) == "-") {
            //음수가 들어왔을때 '-'를 빼고적용되게..
            tmpH = myStr.substring(0, 1);
            myStr = myStr.substring(1, me.length);
        }
        if (myStr.length > 3) {
            var c = 0;
            var myArray = new Array();
            for (var i = myStr.length; i > 0; i = i - 3) {
                myArray[c++] = myStr.substring(i - 3, i);
            }
            myArray.reverse();
            myStr = myArray.join(",");
        }
        if (tmpH) {
            me = tmpH + myStr;
        } else {
            me = myStr;
        }
    }
    return me;
};

/*=============================================================================*
 * 입력값을 소수점 이하 몇 자리까지 보여줄지 정한다.
 * 소수점 이하 자리수가 입력된 값보다 작으면 0으로 채운다.
 * param : sVal 입력스트링, iSize 소수자릿수
 * return : String
 *============================================================================*/
/**
 * @method
 * @name numOnMask4
 * @description desc
 * @param {string} sVal desc
 * @param {string} iSize desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.numOnMask4 = function(sVal, iSize) {
    if (scwin.isNumberDot(sVal)) // 숫자형인지 확인

    {
        var e = sVal;
        e = e.split(".");
        if (!e[1]) {
            if (iSize == 0) {
                sVal = scwin.numOnMask(e[0]);
                return sVal;
            } else {
                e[1] = "0";
            }
        }
        while (e[1].length < iSize) {
            // 주어진 소숫점 이하 자릿수 만큼 뒤에 "0" 추가
            e[1] = e[1] + "0";
        }
        sVal = scwin.numOnMask(e[0]) + "." + e[1].substr(0, iSize);
        return sVal;
    } else {
        return false;
    }
};



