/**
 * @method
 * @name chkValidChar
 * @description desc
 * @param {string} o desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.chkValidChar = function(o) {
    var re = new RegExp("[%\']", "ig");
    var retVal = re.test(o.getValue());
    if (retVal == true) {
        alert("검색어에 다음 문자를 사용할 수 없습니다 : \n\n %,\' ");
        o.setValue("");
        return false;
    } else return true;
};

/**
 * 두 날짜에 며칠 차이나는지 구함
 * from_val이 to_val보다 크면 -붙여서 리턴
 */
/**
 * @method
 * @name getDayInterval
 * @description desc
 * @param {string} from_val desc
 * @param {string} to_val desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getDayInterval = function(from_val, to_val) {
    var day = 1000 * 3600 * 24; //24시간
    if (scwin.isDate(from_val) == false) {
        return;
    }
    if (scwin.isDate(to_val) == false) return;
    var from_date = scwin.toTimeObject(from_val);
    var to_date = scwin.toTimeObject(to_val);
    var day_interval = parseInt((to_date - from_date) / day, 10);
    //alert(to_date+" - "+from_date+"="+day_interval);
    return day_interval;
};


