/* 승인자    : 장정희                                                         */
/* 작업자    : 이성진                                                         */
/**
 * 이메일 정합성 검사
 */
/**
 * @method
 * @name email_chk
 * @description desc
 * @param {string} objEmail desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.email_chk = function(objEmail) {
    var email = objEmail.getValue();
    var invalidChars = "\"|&;!=!*\'\\";
    for (var i = 0; i < invalidChars.length; i++) {
        if (email.indexOf(invalidChars.charAt) != -1) {
            alert("잘못된 이메일 주소입니다.");
            objEmail.focus();
            return false;
        }
    }
    if (email.indexOf("@") == -1) {
        alert("잘못된 이메일 주소입니다. '@'가 없습니다..");
        objEmail.focus();
        return false;
    }
    if (email.indexOf(" ") != -1) {
        alert("잘못된 이메일 주소입니다.");
        objEmail.focus();
        return false;
    }
    if (window.RegExp) {
        var reg1str = "(@.*@)|(\\.\\.)|(@\\.)|(\\.@)|(^\\.)";
        var reg2str = "^.+\\@(\\[?)[a-zA-Z0-9\\-\\.]+\\.([a-zA-Z]{2,3}|[0-9]{1,3})(\\]?)$";
        var reg1 = new RegExp(reg1str);
        var reg2 = new RegExp(reg2str);
        if (reg1.test(email) || !reg2.test(email)) {
            alert("잘못된 이메일 주소입니다.");
            objEmail.focus();
            return false;
        }
    }
    return true;
};


/**
 * Time 스트링을 자바스크립트 Date 객체로 변환
 * parameter time: Time 형식의 String
 */
/**
 * @method
 * @name toTimeObject
 * @description desc
 * @param {string} time desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.toTimeObject = function(time) {
    //parseTime(time)
    var year = time.substr(0, 4);
    var month = time.substr(4, 2) - 1; // 1월=0,12월=11
    var day = time.substr(6, 2);
    return new Date(year, month, day);
};

// readonly나 disabled로 막힌 경우를 제외하고 tabindex 값을 지정하여 입력박스 순서대로 이동
/**
 * @method
 * @name tabIndexing
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.tabIndexing = function() {
    elements = document.all;
    for (i = 0; i < elements.length; i++) {
        if (elements[i].readOnly == false) {
            elements[i].tabIndex = i;
        }
    }
};




