/**
 * @method
 * @name fn_setSysDate
 * @description desc
 * @param {string} fromData desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_setSysDate = function(fromData) {
    var vDate, vMon, vDay;
    vDate = new Date();
    var fromData = document.getElementById(fromData);
    var ie = document.all;
    if (!ie) {
        vDate.setFullYear(vDate.getYear() + 1900);
    } else {
        vDate.setFullYear(vDate.getYear());
    }

    //-- 월 <10
    if ((vDate.getMonth() + 1) < 10) {
        vMon = "0" + String(vDate.getMonth() + 1);
    } else {
        vMon = String(vDate.getMonth() + 1);
    }
    if (vDate.getDate() < 10) {
        vDay = "0" + String(vDate.getDate());
    } else {
        vDay = String(vDate.getDate());
    }
    fromData.setValue(String(vDate.getFullYear()) + "-" + String(vMon) + "-" + String(vDay));
};
