/** 오른쪽 공백 제거 */
/**
 * @method
 * @name funcRtrim
 * @description desc
 * @param {string} str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.funcRtrim = function(str) {
    var src = new String(str);
    var tmp = new String();
    var i, lastnum, len = src.length;
    for (i = len; i >= 0; i--) {
        tmp = src.substring(i, i - 1);
        if (tmp != ' ') {
            lastnum = i;
            break;
        }
    }
    tmp = src.substring(0, lastnum);
    return tmp;
};


/** 왼쪽 공백 제거 */
/**
 * @method
 * @name funcLtrim
 * @description desc
 * @param {string} str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.funcLtrim = function(str) {
    var src = new String(str);
    var tmp = new String();
    var i, firstnum, len = src.length;
    for (i = 0; i < len; i++) {
        tmp = src.substring(i, i + 1);
        if (tmp != ' ') {
            firstnum = i;
            break;
        }
    }
    tmp = src.substring(firstnum);
    return tmp;
};


/** 공백 제거 */
/**
 * @method
 * @name funcTrim
 * @description desc
 * @param {string} str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.funcTrim = function(str) {
    var src = new String(str);
    var tmp = new String();
    tmp = scwin.funcLtrim(scwin.funcRtrim(str));
    return tmp;
};



