 * author : lds010
 */
/**
 * @method
 * @name fnOpenBondDetailInfo
 * @description desc
 * @param {string} bndMktactTpCd desc
 * @param {string} bndApplId desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fnOpenBondDetailInfo = function(bndMktactTpCd, bndApplId) {
    var method = "searchBondsNewListInfo";
    if (bndMktactTpCd.match("111,121,131,141,151")) {
        method = "searchBondsNewListInfo";
    }
    if (bndMktactTpCd.match("305")) {
        method = "searchBondsAddListInfo";
    }
    if (bndMktactTpCd.match("303,304")) {
        method = "searchBondsHalfwyReamptInfo";
    }
    if (bndMktactTpCd.match("302,315")) {
        method = "searchBondsExerInfo";
    }
    var url = "/disclosure/bonds.do?method=" + method + "&bndApplId=" + bndApplId;
    window.open(url, '채권상장', 'scrollbars=yes,toolbar=no,resizable=no,width=800,height=480,left=0,top=0,status=yes');
};


/*
 * Table TR Row 색깔을 mode에 따라 변경한다.
 * TRobj : TR 객체
 * mode : in(커서가 객체로 에 들어왔을 때), out(커서가 객체에서 나갔을 때)
 * trstat : 0 - TR이 무색인 경우, 1 - TR이 유색인 경우
 * author : lds010
 */
/**
 * @method
 * @name changeTableRowColor
 * @description desc
 * @param {string} TRobj desc
 * @param {string} mode desc
 * @param {string} trstat desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.changeTableRowColor = function(TRobj, mode, trstat) {
    if (mode == "in") {
        TRobj.style.backgroundColor = '#D9E6E5';
    } else if (mode == "out") {
        if (trstat == "0") {
            TRobj.style.backgroundColor = '#FFFFFF';
        } else if (trstat == "1") {
            TRobj.style.backgroundColor = '#F5F5F5';
        }
    }
};




/**
 * 조회 조건 값의 유효성 확인
 * fromDateObj : 시작일 input object
 * toDateObj   : 종료일 input object
 * author : lds010
 */
/**
 * @method
 * @name checkDateValidation
 * @description desc
 * @param {string} fromDateObj desc
 * @param {string} toDateObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.checkDateValidation = function(fromDateObj, toDateObj) {
    var fromDate = fromDateObj.getValue();
    var toDate = toDateObj.getValue();
    var message = null;
    //시작날짜 길이 확인
    if (fromDate != "") {
        if (toDate == "") {
            alert("종료일을 입력해주세요.");
            toDateObj.focus();
            return false;
        }
        if (fromDate.length != 10) {
            alert("날짜 형식이 맞지 않습니다.");
            fromDateObj.focus();
            return false;
        }
    }
    //종료날짜 길이 확인
    if (toDate != "") {
        if (fromDate == "") {
            alert("시작일을 입력해주세요.");
            fromDate.focus();
            return false;
        }
        if (toDate.length != 10) {
            alert("날짜 형식이 맞지 않습니다.");
            toDateObj.focus();
            return false;
        }
    }
    //시작일, 종료일 크기 확인
    if (fromDate != "" && toDate != "") {
        if (scwin.validateStartDateAndToDate(fromDate, toDate) == false) {
            message = "시작일이 종료일 보다 최근 날짜입니다. 기간을 정확히 입력해주세요.";
            alert(message);
            return false;
        }
    }
    return true;
};

/**
 * 시작날짜와 종료날짜 정합성 체크
 * 사용예) validate(frm.fromDate.value, frm.toDate.value)
 * author : lds010
 */
/**
 * @method
 * @name validateStartDateAndToDate
 * @description desc
 * @param {string} fromDateVal desc
 * @param {string} toDateVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.validateStartDateAndToDate = function(fromDateVal, toDateVal) {
    var fromDateVal = fromDateVal.replace(/\-/g, '');
    var toDateVal = toDateVal.replace(/\-/g, '');
    if (Number(fromDateVal) > Number(toDateVal)) {
        return false;
    } else {
        return true;
    }
};


/**
 * 시작날짜와 종료날짜 정합성 체크 (범위)
 * 사용예) validate(frm.fromDate.value, frm.toDate.value)
 * author : lds010
 */
/**
 * @method
 * @name validateStartDateAndToDateWithRange
 * @description desc
 * @param {string} fromDateVal desc
 * @param {string} toDateVal desc
 * @param {string} range desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.validateStartDateAndToDateWithRange = function(fromDateVal, toDateVal, range) {
    var fromDateVal = fromDateVal.replace(/\-/g, '');
    var toDateVal = toDateVal.replace(/\-/g, '');
    var frm = Number(fromDateVal);
    var to = Number(toDateVal);
    //alert(to - frm);
    if (frm < to) {
        var tmpVal = to - frm;
        if (tmpVal > range) {
            return false;
        } else {
            return true;
        }
    }
    return false;
};


/**
 * 조회 조건 값의 유효성 확인
 * fromObj : 시작값 input object
 * toObj   : 종료값 input object
 * author : lds010
 */
/**
 * @method
 * @name compareTwoValueOfAccnt
 * @description desc
 * @param {string} accntName desc
 * @param {string} fromObj desc
 * @param {string} toObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.compareTwoValueOfAccnt = function(accntName, fromObj, toObj) {
    //alert("compareTwoValueOfAccnt");

    var fromVal = fromObj.val();
    var toVal = toObj.val();
    var message = "";

    //시작일, 종료일 크기 확인
    if (fromVal != "" && toVal != "") {
        if (scwin.validateStartEndValue(fromVal, toVal) == false) {
            message = accntName + "의 시작값이 종료값 보다 큽니다.\n값의 범위를 정확히 입력해주세요.";
            alert(message);
            return false;
        }
    }
    return true;
};
/**
 * @method
 * @name validateStartEndValue
 * @description desc
 * @param {string} startVal desc
 * @param {string} endVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.validateStartEndValue = function(startVal, endVal) {
    var startVal = startVal.replace(/,/g, "");
    var endVal = endVal.replace(/,/g, "");
    if (Number(startVal) > Number(endVal)) {
        return false;
    } else {
        return true;
    }
};
/**
 * @method
 * @name gShowWindow
 * @description desc
 * @param {string} strPageURL desc
 * @param {string} strWindowName desc
 * @param {string} lngWidth desc
 * @param {string} lngHeight desc
 * @param {string} strOptions desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.gShowWindow = function(strPageURL, strWindowName, lngWidth, lngHeight, strOptions) {
    var lngTop, lngLeft;
    if (strOptions == "") {
        strOptions = "toolbar=no, location=no, menubar=no, scrollbars=yes, status=yes, resizable=no";
    }
    lngTop = (window.screen.height - lngHeight) / 2;
    lngLeft = (window.screen.width - lngWidth) / 2;
    strOptions = strOptions + ", width=" + lngWidth + ", height=" + lngHeight + ", top=" + lngTop + ", left=" + lngLeft;
    var newWin = window.open(strPageURL, strWindowName, strOptions);
    //newWin.focus();
};



