/**
 * file객체와 Array타입의 file객체와 fileType과
 */
/**
 * @method
 * @name LimitAttach
 * @description desc
 * @param {string} obj desc
 * @param {string} fileType desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.LimitAttach = function(obj, fileType) {
    var file = obj.getValue();
    allowSubmit = true;
    if (!file) return;
    while (file.indexOf("\\") != -1) {
        file = file.slice(file.indexOf("\\") + 1);
    }
    ext = file.slice(file.indexOf(".")).toLowerCase();
    for (var i = 0; i < fileType.length; i++) {
        if (fileType[i] == ext) {
            allowSubmit = false;
            break;
        }
    }
    if (!allowSubmit) {
        alert((fileType.join("  ")) + "확장자를 가진 파일은 업로드할 수 없습니다.\n다시 파일을 선택하십시오.");
        obj.focus();
        return false;
    }
    return true;
};
/**
 * @method
 * @name chkStrNull
 * @description desc
 * @param {string} str desc
 * @param {string} field desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.chkStrNull = function(str, field) {
    if (str.getValue() == null || str.getValue() == "") {
        alert(field + "을(를) 입력하세요.");
        str.select();
        str.focus();
        return false;
    }
    return true;
};
/**
 * @method
 * @name chkStrNullLength
 * @description desc
 * @param {string} str desc
 * @param {string} field desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.chkStrNullLength = function(str, field) {
    var strNull = false;
    var strLength = false;
    strNull = scwin.chkStrNull(str, field);
    if (!strNull) {
        return false;
    } else {
        strLength = scwin.chkStrLength(str, field);
        if (!strLength) {
            return false;
        }
    }
    return true;
};


/**
 * 텍스트필드의 정수(음수포함)값에 콤마를 붙인다.
 * tfObj : 텍스트필드 객체
 * 사용예) onkeyup='setNumberTypeWithComma(this)'
 */
/**
 * @method
 * @name setNumberTypeWithComma
 * @description desc
 * @param {string} tfObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.setNumberTypeWithComma = function(tfObj) {
    scwin.setNumberTypeWithComma1(tfObj, '-int');
};
/**
 * @method
 * @name setNumberTypeWithComma1
 * @description desc
 * @param {string} tfObj desc
 * @param {string} type desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.setNumberTypeWithComma1 = function(tfObj, type) {
    /*
    type
    -> 'int' : 양의 정수
    -> 'float' : 양의 실수
    -> '-int' : 음의 정수 포함
    -> '-float' : 음의 실수 포함
    */
    temp_value = tfObj.getValue().toString();

    /*
    while(temp_value.indexOf(",") > -1) {
      temp_value = temp_value.replace(",", "");
    }
    */

    //먼저 컴마 제거 필요
    var num = new String(tfObj.getValue());
    num = num.replace(/,/gi, "");
    regexp = /[^-\.0-9]/g;
    repexp = '';
    temp_value = temp_value.replace(regexp, repexp);
    regexp = '';
    repexp = '';
    switch (type) {
        case 'int':
            regexp = /[^0-9]/g;
            break;
        case 'float':
            regexp = /^(-?)([0-9]*)(\.?)([^0-9]*)([0-9]*)([^0-9]*)/;
            break;
        case '-int':
            regexp = /^(-?)([0-9]*)([^0-9]*)([0-9]*)([^0-9]*)/;
            break;
        case '-float':
            regexp = /^(-?)([0-9]*)(\.?)([^0-9]*)([0-9]*)([^0-9]*)/;
            break;
        default:
            regexp = /[^0-9]/g;
            break;
    }
    switch (type) {
        case 'int':
            repexp = '';
            break;
        case 'float':
            repexp = '$2$3$5';
            break;
        case '-int':
            repexp = '$1$2$4';
            break;
        case '-float':
            repexp = '$1$2$3$5';
            break;
        default:
            regexp = /[^0-9]/g;
            break;
    }
    temp_value = temp_value.replace(regexp, repexp);
    //tfObj.value = temp_value;

    if (temp_value == '-') {
        tfObj.setValue(temp_value);
        return;
    }

    //컴마를 붙임
    tfObj.setValue(scwin.applyComma(temp_value));
};
/**
 * @method
 * @name applyComma
 * @description desc
 * @param {string} num desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.applyComma = function(num) {
    var sign = "";
    if (isNaN(num)) {
        alert("숫자만 입력할 수 있습니다.");
        return 0;
    }
    if (num == 0) {
        return num;
    }
    if (num < 0) {
        num = num * (-1);
        sign = "-";
    } else {
        num = num * 1;
    }
    num = new String(num);
    var temp = "";
    var pos = 3;
    num_len = num.length;
    while (num_len > 0) {
        num_len = num_len - pos;
        if (num_len < 0) {
            pos = num_len + pos;
            num_len = 0;
        }
        temp = "," + num.substr(num_len, pos) + temp;
    }
    return sign + temp.substr(1);
};

/* 년,월,일 계산 
 *  sDate :날짜 nNum : 차이 type:년,월,일
 */
/**
 * @method
 * @name dateAddDel
 * @description desc
 * @param {string} sDate desc
 * @param {string} nNum desc
 * @param {string} type desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.dateAddDel = function(sDate, nNum, type) {
    var d;
    var yy = parseInt(sDate.substr(0, 4), 10);
    var mm = parseInt(sDate.substr(5, 2), 10);
    var dd = parseInt(sDate.substr(8), 10);
    if (type == "d") {
        d = new Date(yy, mm - 1, dd + nNum);
    } else if (type == "m") {
        d = new Date(yy, mm + nNum, -1);
        if (d.getDate() + 1 < dd) {
            dd = d.getDate() + 1;
        }
        d = new Date(yy, mm - 1 + nNum, dd);
    } else if (type == "y") {
        d = new Date(yy + nNum, mm, -1);
        if (d.getDate() + 1 < dd) {
            dd = d.getDate() + 1;
        }
        d = new Date(yy + nNum, mm - 1, dd);
    }
    yy = d.getFullYear();
    mm = d.getMonth() + 1;
    dd = d.getDate();
    mm = scwin.setDateMmDd(mm);
    dd = scwin.setDateMmDd(dd);
    return '' + yy + '-' + mm + '-' + dd;
};
/**
 * @method
 * @name setDateMmDd
 * @description desc
 * @param {string} dd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.setDateMmDd = function(dd) {
    dd = (dd < 10) ? '0' + dd : dd;
    return dd;
};
